package br.com.sussmartcare.notification.infrastructure; import jakarta.persistence.*; import java.util.*; @Entity @Table(name="visit_patient_links") public class VisitPatientLink{@Id private UUID visitId;@Column(nullable=false)private UUID patientId;protected VisitPatientLink(){}public VisitPatientLink(UUID v,UUID p){visitId=v;patientId=p;}public UUID getVisitId(){return visitId;}public UUID getPatientId(){return patientId;}public void reassignPatient(UUID canonical){patientId=canonical;}}